insert into public.products (slug, category_id, name, price, description, specs, image, image_credit, stock)
select v.slug, c.id, v.name, v.price, v.description, v.specs::jsonb, v.image, v.credit::jsonb, v.stock
from (values
  ('uno-r4-minima', 'boards', '아두이노 우노 R4 미니마 (정품)', 26950, 'Renesas RA4M1 기반으로 R3보다 메모리와 속도가 향상된 차세대 아두이노 우노 보드입니다.', '{"MCU": "Renesas RA4M1 (Cortex-M4)", "클럭": "48MHz", "메모리": "256KB Flash / 32KB RAM", "포트": "USB-C"}', '/images/products/uno-r4-minima.webp', '{"author": "Arduino", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Arduino_Uno_R4_Minima_perspective.webp"}', 103),
  ('uno-r4-wifi', 'boards', '아두이노 우노 R4 WiFi (정품)', 42130, 'ESP32-S3 무선 모듈과 12x8 LED 매트릭스를 내장한 IoT용 우노 R4 보드입니다.', '{"MCU": "Renesas RA4M1 + ESP32-S3", "무선": "Wi-Fi / Bluetooth", "부가기능": "12x8 LED 매트릭스", "포트": "USB-C"}', '/images/products/uno-r4-wifi.webp', '{"author": "Arduino", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Arduino_Uno_R4_WiFi_perspective.webp"}', 117),
  ('uno-r3', 'boards', '아두이노 우노 R3 (정품)', 31900, '아두이노 입문자가 가장 많이 사용하는 ATmega328P 기반의 표준 보드입니다.', '{"MCU": "ATmega328P", "동작전압": "5V", "디지털 I/O": "14핀", "아날로그 입력": "6핀"}', '/images/products/uno-r3.jpg', '{"author": "SparkFun Electronics from Boulder, USA", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Arduino_Uno_-_R3.jpg"}', 32),
  ('nano-every', 'boards', '아두이노 나노 에브리 (정품)', 20790, 'ATmega4809를 탑재한 작고 강력한 나노 폼팩터 보드로 브레드보드 실습에 적합합니다.', '{"MCU": "ATmega4809", "동작전압": "5V", "클럭": "20MHz", "크기": "45 x 18mm"}', '/images/products/nano-every.png', '{"author": "Enirstad", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Arduino_Nano_Every.png"}', 56),
  ('nano-esp32', 'boards', '아두이노 나노 ESP32 (정품)', 27390, 'ESP32-S3 기반으로 Wi-Fi와 블루투스를 지원하는 IoT·마이크로파이썬용 나노 보드입니다.', '{"MCU": "ESP32-S3 (u-blox NORA-W106)", "무선": "Wi-Fi / Bluetooth LE", "동작전압": "3.3V", "포트": "USB-C"}', '/images/products/nano-esp32.jpg', '{"author": "David Mellis", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:Arduino_Nano.jpg", "note": "유사 제품 사진"}', 94),
  ('mega-2560', 'boards', '아두이노 메가 2560 R3 (정품)', 64900, '54개의 디지털 핀과 16개의 아날로그 입력을 갖춘 대형 프로젝트용 보드입니다.', '{"MCU": "ATmega2560", "디지털 I/O": "54핀", "아날로그 입력": "16핀", "플래시 메모리": "256KB"}', '/images/products/mega-2560.jpg', '{"author": "Dsimic", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Arduino_MEGA_2560_R3,_front_side.jpg"}', 106),
  ('leonardo', 'boards', '아두이노 레오나르도 (정품, 헤더 포함)', 38500, 'USB HID 기능을 내장해 키보드·마우스로 인식시킬 수 있는 ATmega32u4 기반 보드입니다.', '{"MCU": "ATmega32u4", "디지털 I/O": "20핀", "동작전압": "5V", "포트": "Micro USB"}', '/images/products/leonardo.jpg', '{"author": "Kszapsza", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Arduino_Leonardo_board_(cropped).JPG"}', 25),
  ('hc-sr04', 'sensors', 'HC-SR04 초음파 거리센서 모듈', 1210, '초음파를 이용해 2cm~4m 거리의 물체까지 거리를 측정하는 센서입니다.', '{"측정거리": "2cm ~ 400cm", "동작전압": "5V", "측정각도": "15°"}', '/images/products/hc-sr04.jpg', '{"author": "SparkFun", "license": "CC BY 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:SparkFun_HC-SR04_Ultrasonic-Sensor_13959-01a.jpg"}', 177),
  ('dht11', 'sensors', 'DHT11 온습도 센서 모듈', 1760, '온도와 습도를 디지털 신호로 출력하는 저가형 입문용 센서 모듈입니다.', '{"온도범위": "0 ~ 50℃ (±2℃)", "습도범위": "20 ~ 90% RH (±5%)", "동작전압": "3.3V ~ 5V", "출력": "디지털 단일 버스"}', '/images/products/dht11.jpg', '{"author": "Crackopl", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:Dht11_term_and_humidity_sensor.jpg"}', 122),
  ('dht22', 'sensors', 'DHT22 (AM2302) 온습도 센서', 6490, 'DHT11보다 넓은 측정 범위와 높은 정밀도를 가진 디지털 온습도 센서입니다.', '{"온도범위": "-40 ~ 80℃ (±0.5℃)", "습도범위": "0 ~ 100% RH (±2%)", "동작전압": "3.3V ~ 5.5V"}', '/images/products/dht22.jpg', '{"author": "Suyash Dwivedi", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:AM2302_(DHT22)_digital_temperature_and_humidity_sensor_module.jpg"}', 88),
  ('pir-hc-sr501', 'sensors', 'HC-SR501 PIR 인체감지 센서 모듈', 1650, '사람의 움직임을 적외선으로 감지해 디지털 신호를 출력하는 센서 모듈입니다.', '{"동작전압": "5V ~ 20V", "감지거리": "최대 약 7m", "감지각도": "약 120°", "출력": "디지털 (High/Low)"}', '/images/products/pir-hc-sr501.jpg', '{"author": "tvluke_", "license": "CC0 1.0", "source_url": "https://www.flickr.com/photos/169136682@N02/40640949883"}', 64),
  ('soil-moisture', 'sensors', '토양 수분(습도) 센서 모듈', 1100, '흙 속의 수분량을 측정해 화분 자동 급수 등 스마트팜 실습에 활용하는 센서입니다.', '{"동작전압": "3.3V ~ 5V", "출력": "아날로그 / 디지털", "비교기": "LM393"}', '/images/products/soil-moisture.jpg', '{"author": "SparkFun Electronics", "license": "CC BY 2.0", "source_url": "https://www.flickr.com/photos/41898857@N04/35799069006", "note": "유사 제품 사진"}', 159),
  ('mpu6050', 'sensors', 'MPU-6050 6축 자이로/가속도 센서 모듈 (GY-521)', 4950, '3축 가속도와 3축 자이로를 하나로 측정해 기울기·움직임을 감지하는 센서 모듈입니다.', '{"칩": "MPU-6050", "통신": "I2C", "동작전압": "3.3V ~ 5V", "측정축": "가속도 3축 + 자이로 3축"}', '/images/products/mpu6050.jpg', '{"author": "Nevit Dilmen", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:GY-521_MPU-6050_Module_3_Axis_Gyroscope_%2B_Accelerometer_0487.jpg"}', 135),
  ('cds-photoresistor', 'sensors', 'CdS 조도센서 (GL5537, 5mm)', 550, '빛의 밝기에 따라 저항값이 변하는 조도센서로 자동 조명 실습에 사용합니다.', '{"모델": "GL5537", "크기": "5파이 (5mm)", "타입": "광저항 (LDR)"}', '/images/products/cds-photoresistor.jpg', '{"author": "Nevit Dilmen", "license": "CC BY-SA 3.0", "source_url": "https://commons.wikimedia.org/wiki/File:LDR_1480405_6_7_HDR_Enhancer_1.jpg"}', 24),
  ('sg90', 'motors', 'SG90 9g 미니 서보모터', 2090, '0~180도 각도 제어가 가능한 가장 대표적인 소형 서보모터입니다.', '{"토크": "1.8kg·cm (4.8V)", "속도": "0.1초/60°", "동작전압": "4.8V ~ 6V", "무게": "9g"}', '/images/products/sg90.jpg', '{"author": "Suyash Dwivedi", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:Tower_Pro_SG90_micro_servo_motor.jpg"}', 105),
  ('stepper-28byj48', 'motors', '28BYJ-48 5V 스텝모터 + ULN2003 드라이버', 2860, '정밀한 회전 각도 제어를 배울 수 있는 5V 스텝모터와 전용 드라이버 세트입니다.', '{"동작전압": "5V", "상": "4상 5선", "기어비": "1:64", "드라이버": "ULN2003"}', '/images/products/stepper-28byj48.jpg', '{"author": "Kushagra Keshari", "license": "CC BY-SA 4.0", "source_url": "https://commons.wikimedia.org/wiki/File:28BYJ-48_unipolar_stepper_motor_with_ULN2003_driver.jpg"}', 54),
  ('l298n', 'motors', 'L298N 듀얼 모터 드라이버 모듈', 2970, 'DC 모터 2개 또는 스텝모터 1개를 정·역회전 제어할 수 있는 H-브리지 드라이버입니다.', '{"칩": "L298N", "모터전압": "5V ~ 35V", "최대전류": "채널당 2A", "채널": "2채널"}', '/images/products/l298n.jpg', '{"author": "kenming Wang", "license": "CC BY-SA 2.0", "source_url": "https://www.flickr.com/photos/12882975@N00/14134165312", "note": "유사 제품 사진"}', 138),
  ('dc-motor-tt', 'motors', 'TT 기어 DC 모터 (스마트카용)', 9350, 'RC카·스마트카 제작에 많이 쓰이는 노란색 감속 기어 DC 모터입니다.', '{"동작전압": "3V ~ 6V", "타입": "감속 기어 DC 모터", "용도": "스마트카 / 로봇 바퀴 구동"}', '/images/products/dc-motor-tt.jpg', '{"author": "SparkFun Electronics", "license": "CC BY 2.0", "source_url": "https://www.flickr.com/photos/41898857@N04/18235038862"}', 40),
  ('lcd1602-i2c', 'displays', '1602 I2C 캐릭터 LCD 모듈', 2750, '16x2 문자를 표시하며 I2C 모듈이 부착되어 선 4개로 간단히 연결할 수 있습니다.', '{"표시": "16문자 x 2줄", "통신": "I2C", "백라이트": "블루 / 흰색 문자", "동작전압": "5V"}', '/images/products/lcd1602-i2c.jpg', '{"author": "oomlout", "license": "CC BY-SA 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:16x2_Character_LCD_Display.jpg"}', 117),
  ('oled-096', 'displays', '0.96인치 OLED 디스플레이 모듈 (I2C, SSD1306)', 10780, '백라이트 없이 선명한 128x64 해상도의 소형 OLED 디스플레이입니다.', '{"크기": "0.96인치", "해상도": "128 x 64", "드라이버": "SSD1306", "통신": "I2C"}', '/images/products/oled-096.jpg', '{"author": "kasparsdambis", "license": "CC BY 2.0", "source_url": "https://www.flickr.com/photos/87890875@N06/36735944063"}', 103),
  ('max7219-matrix', 'displays', 'MAX7219 8x8 도트 매트릭스 모듈', 2420, 'MAX7219 드라이버로 64개의 LED를 3개의 핀만으로 제어하는 도트 매트릭스 모듈입니다.', '{"드라이버": "MAX7219", "LED": "8 x 8 (64개)", "동작전압": "5V", "통신": "SPI"}', '/images/products/max7219-matrix.jpg', '{"author": "alvaropgl", "license": "CC BY-SA 2.0", "source_url": "https://www.flickr.com/photos/23715458@N02/2685950514", "note": "유사 제품 사진"}', 43),
  ('breadboard-830', 'parts', '830홀 브레드보드 (MB-102)', 1540, '납땜 없이 회로를 구성할 수 있는 표준 크기 830홀 브레드보드입니다.', '{"홀 수": "830홀", "규격": "MB-102", "크기": "165 x 55mm"}', '/images/products/breadboard-830.jpg', '{"author": "oomlout", "license": "CC BY-SA 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:BREB-02_(14335226011).jpg"}', 19),
  ('jumper-wires', 'parts', '점퍼 와이어 M-M 40P (20cm)', 935, '브레드보드와 아두이노를 연결하는 수-수 타입 40가닥 컬러 점퍼 케이블입니다.', '{"타입": "M-M (수-수)", "수량": "40가닥", "길이": "20cm", "피치": "2.54mm"}', '/images/products/jumper-wires.jpg', '{"author": "oomlout", "license": "CC BY-SA 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:A_few_Jumper_Wires.jpg"}', 189),
  ('led-kit', 'parts', '5mm LED 모음 (5색 x 10개)', 3300, '빨강·초록·파랑·노랑·흰색 5mm LED를 모은 기초 실습용 세트입니다.', '{"크기": "5mm", "색상": "5색", "수량": "50개", "전류": "20mA"}', '/images/products/led-kit.jpg', '{"author": "SparkFun Electronics", "license": "CC BY 2.0", "source_url": "https://www.flickr.com/photos/41898857@N04/11072714034"}', 195),
  ('resistor-kit', 'parts', '아두이노 막대저항 키트 (5종 250개)', 1980, '아두이노 실습에 자주 쓰는 저항값 5종을 모은 저항 키트입니다.', '{"저항값": "220Ω, 470Ω, 1KΩ, 4.7KΩ, 10KΩ", "수량": "5종 x 50개", "전력": "1/4W"}', '/images/products/resistor-kit.jpg', '{"author": "oomlout", "license": "CC BY-SA 2.0", "source_url": "https://www.flickr.com/photos/33504192@N00/3703849663"}', 33),
  ('usb-cable', 'parts', 'USB A to B 케이블 (1.5m)', 3410, '아두이노 우노·메가 보드를 PC에 연결하는 USB 2.0 A-B 타입 케이블입니다.', '{"타입": "USB-A (M) to USB-B (M)", "규격": "USB 2.0", "길이": "1.5m"}', '/images/products/usb-cable.jpg', '{"author": "oomlout", "license": "CC BY-SA 2.0", "source_url": "https://commons.wikimedia.org/wiki/File:A-B_Usb_Cable.jpg"}', 94),
  ('starter-kit', 'kits', '아두이노 스타터 키트 한글판 (정품)', 152900, '우노 보드와 기초 부품, 15가지 프로젝트 한글 가이드북이 포함된 공식 입문 키트입니다.', '{"구성": "Arduino UNO + 부품 일체", "프로젝트": "15가지", "가이드북": "한글판", "모델": "K120007"}', '/images/products/starter-kit.jpg', '{"author": "Ultra-lab", "license": "CC BY-SA 2.0", "source_url": "https://www.flickr.com/photos/62141688@N08/16624491097", "note": "영문/스페인어판 사진"}', 192)
) as v(slug, category, name, price, description, specs, image, credit, stock)
join public.categories c on c.slug = v.category;

